method.testScript:
const t = document.body.innerText;
return t.includes('Started Document Data Refresh Job')
	&& t.includes('Document Data Refresh requested for [admin].[DataGroup] Completed')
	&& t.includes('Finished Document Data Refresh Job')
	&& ! t.includes('[admin].[Contact]');

const t = document.body.innerText;
return /Dispatch Status:\s*SKIPPED/.test(t)
	&& /Relay Status:\s*skipped/.test(t)
	&& /Relay Detail:\s*testBogusSend/.test(t)
	&& t.includes('ops' + sail.run + '@example.com')
	&& /Subject:\s*Perform Document Data Refresh - Complete/.test(t)
	&& /Mail Count:\s*1\b/.test(t);

method.execute:
const t = document.body.innerText;
const h = t.search(/\nconversations\nEvictions/);
const d = t.indexOf('\nDisk\n', h);
return /Entries:\s*(\d+)/.exec(t.substring(d))[1];

method.testScript:
const t = document.body.innerText;
const h = t.search(/\nconversations\nEvictions/);
const d = t.indexOf('\nDisk\n', h);
return Number(/Entries:\s*(\d+)/.exec(t.substring(d))[1]) < Number(sail.vars.conversationsBefore);
